{
  "world_id": "wld_feathers_over_the_mist",
  "name": "The Hushed Archipelago of Sennen",
  "description": "Sennen is a chain of fog-bound islands where wuxia fantasy plays out in a lyrical key. Sword sects hold the high terraces, fishing clans hold the shores, and wheeling over both are the red-crowned cranes. The cranes nest only in the reed rookeries of the lowland marshes. The islanders believe each crane carries one drowned name across the mist to the afterlife. A feud between three rival sects has spread from duels to burned fields, and now to the rookeries themselves. Sixteen-year-old Ishi Maren was disowned by her sword lineage. She inherits her late master's tally-stick, a notched cedar rod that records every oath the old master ever brokered. Only a peace moot called by that stick can bind the sects. She must carry it across the island's sacred places to three rival sects, and she must persuade each of them before the last crane rookery burns. The world is quiet, ceremonial and tender, and its violence is always formal. Grief and honour are described through weather, feathers and the sound of bells in fog.",
  "locations": [
    {
      "id": "loc_reedwater_rookery",
      "name": "Reedwater Rookery",
      "description": "A vast tidal marsh of silver reeds where the last great flocks of cranes nest. At dawn the birds dance in the shallows, and the dancing is read by the sects as an omen. Two of its nine nesting islets are already scorched."
    },
    {
      "id": "loc_hollow_bell_pass",
      "name": "Hollow Bell Pass",
      "description": "A narrow mountain road hung with thousands of bronze bells. They ring when mist touches them, so no traveller can pass unheard. The bells are the reason ambush is considered both impossible and shameful here. Every sect treats the pass as neutral ground."
    },
    {
      "id": "loc_ninefold_terrace",
      "name": "Ninefold Terrace",
      "description": "The cliffside stronghold of the sword sects, built as nine stacked training courts. The upper courts lie in permanent cloud. Formal challenges are posted on its lacquered boards and answered at its stone duelling ring."
    },
    {
      "id": "loc_drowned_lantern_quay",
      "name": "Drowned Lantern Quay",
      "description": "A fishing harbour whose dead are honoured by sinking paper lanterns weighted with their names. Mist-brokers, ferrymen and storytellers gather here. It is the only place where all three sects will agree to sit together, and so the site of the proposed moot."
    }
  ],
  "factions": [
    {
      "id": "fac_white_plume_school",
      "name": "White Plume School",
      "description": "An austere sect of sword-dancers who model their forms on the movements of cranes. They revere the birds, yet their rigid code has led them to demand blood for a slain elder.",
      "location_ids": ["loc_ninefold_terrace", "loc_reedwater_rookery"]
    },
    {
      "id": "fac_iron_tide_clan",
      "name": "Iron Tide Clan",
      "description": "A seafaring sect of heavy-blade fighters who control the ferries and the harbour. They resent the highland schools and have started burning marsh reeds to deny their rivals refuge.",
      "location_ids": ["loc_drowned_lantern_quay"]
    },
    {
      "id": "fac_bellkeepers_of_the_pass",
      "name": "Bellkeepers of the Pass",
      "description": "A sect of blind sentinels and archers who tend the bells and keep the neutrality of the road. Each keeper memorises one tone as a lifelong vow. They are secretly weary of the feud and quietly hostile to the other two sects.",
      "location_ids": ["loc_hollow_bell_pass", "loc_ninefold_terrace"]
    },
    {
      "id": "fac_lantern_brokers",
      "name": "Lantern Brokers",
      "description": "Neutral go-betweens who sink and read the harbour's name-lanterns. They hold the only record of who has sworn what to whom, and they serve as witnesses for oaths.",
      "location_ids": ["loc_drowned_lantern_quay"]
    }
  ],
  "rules": [
    {
      "id": "rul_formal_challenge",
      "statement": "Duels are settled only by formal challenge, posted openly and answered at a ring. Ambush, poison and night attack are never permitted, and anyone who attacks without challenge is cast out by every sect.",
      "category": "social"
    },
    {
      "id": "rul_tally_stick_binds",
      "statement": "A tally-stick notched by a recognised master can call a peace moot. A sect that refuses to attend loses its right to issue challenges until the next autumn tide.",
      "category": "social"
    },
    {
      "id": "rul_crane_carries_names",
      "statement": "It is held as truth that each crane carries one drowned name over the mist, and when a crane dies its carried name is lost for ever. Killing a crane is therefore the gravest sacrilege.",
      "category": "metaphysics"
    },
    {
      "id": "rul_mist_hides_distance",
      "statement": "Mist on Sennen swallows sight but not sound. Bells, voices and wingbeats carry farther in fog, and no one can move unheard through a bell-hung place.",
      "category": "physics"
    },
    {
      "id": "rul_blade_forms_only",
      "statement": "Fighting depends on blades, bows and trained inner breath. Explosive powders are unknown and the sects' arts rely on discipline instead.",
      "category": "technology"
    },
    {
      "id": "rul_breath_cost",
      "statement": "Inner breath techniques let a swordsman leap, glide and cut at a distance, but each use drains the body, and overuse leaves the practitioner frail for days.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_founding_of_bells",
      "name": "The Hanging of the First Bell",
      "description": "The first sentinels hung bronze bells across the pass after a massacre in the fog, declaring the road neutral for all time.",
      "era": "Age of Sundered Clans",
      "location_ids": ["loc_hollow_bell_pass"]
    },
    {
      "id": "evt_tally_of_nine_oaths",
      "name": "The Tally of Nine Oaths",
      "description": "Master Ishi Torren brokered nine peace oaths among the sects and notched each one into a cedar tally-stick, establishing the stick as a binding instrument.",
      "era": "Age of Quiet Swords",
      "location_ids": ["loc_drowned_lantern_quay", "loc_ninefold_terrace"]
    },
    {
      "id": "evt_elder_slain",
      "name": "The Slaying of Elder Hosai",
      "description": "A White Plume elder fell in a duel whose terms are still disputed. The school claims the Iron Tide cheated, and the feud began here.",
      "era": "Age of Smouldering Feud",
      "location_ids": ["loc_ninefold_terrace"]
    },
    {
      "id": "evt_first_reed_fire",
      "name": "The First Reed Fire",
      "description": "Iron Tide raiders set fire to two nesting islets in the marsh. Hundreds of cranes died, and their carried names were lost.",
      "era": "Age of Smouldering Feud",
      "location_ids": ["loc_reedwater_rookery"]
    },
    {
      "id": "evt_maren_disowned",
      "name": "The Disowning of Maren",
      "description": "Maren was cast out of her lineage for refusing to duel on behalf of a feud she thought false. Her master died soon after and left her the tally-stick.",
      "era": "Age of Smouldering Feud",
      "location_ids": ["loc_ninefold_terrace"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_plume_versus_tide",
      "name": "The Disputed Duel of Elder Hosai",
      "description": "White Plume School and Iron Tide Clan trade burnings and challenges over a duel neither will concede was fair. The cranes' marshes are now the front line.",
      "faction_ids": ["fac_white_plume_school", "fac_iron_tide_clan"]
    },
    {
      "id": "cnf_bells_neutrality",
      "name": "The Strain on the Bells",
      "description": "Both warring sects demand that the Bellkeepers take a side. If the keepers abandon their neutrality, the pass loses its protection and ambush becomes possible for the first time in centuries.",
      "faction_ids": ["fac_bellkeepers_of_the_pass", "fac_white_plume_school", "fac_iron_tide_clan"]
    },
    {
      "id": "cnf_brokers_ledger",
      "name": "The Brokers' Ledger",
      "description": "The Lantern Brokers' records suggest that Elder Hosai's duel terms were altered, but revealing this would shame the White Plume and prove the Iron Tide's claim. The truth could end the feud or deepen it.",
      "faction_ids": ["fac_lantern_brokers", "fac_white_plume_school", "fac_iron_tide_clan"]
    }
  ]
}

