response.output:
{
  "world_id": "wld_court_of_columns",
  "name": "The Court of Columns",
  "description": "A mythic afterlife run as a vast bureaucracy of accounts. Every mortal soul is a ledger entry, and its fate is the sum of its columns: Debts, Gifts, Silences and Oaths. Dead scribes copy, audit and carry these entries upward through ever more exalted counting-houses until the soul is weighed in the Hall of Reckoning. The tone is wry and solemn, for the clerks are petty, tired and proud, yet their arithmetic decides eternity. The dead cannot return to life, and only their accounts move. A mistake in a column is therefore the one thing that can still change a person's end, and fixing it means climbing a ladder of rival offices before the scales fall.",
  "locations": [
    {
      "id": "loc_threshold_registry",
      "name": "The Threshold Registry",
      "description": "A low, damp hall at the river's edge where new souls are first entered into the ledger. Junior scribes sit on stools of driftwood, copying lives from the dying breath of the recently dead. Haste here breeds the errors that travel furthest."
    },
    {
      "id": "loc_pennyweight_counting_house",
      "name": "The Pennyweight Counting-House",
      "description": "A cramped middle office of brass rails, abacus-walls and ink-stained stairwells. Every claim of correction must be stamped here, and the queue is said to be longer than the river. Its clerks measure a soul's worth in grains of regret."
    },
    {
      "id": "loc_ashen_scriptorium",
      "name": "The Ashen Scriptorium",
      "description": "An archive where superseded ledger pages are burned and their ashes pressed into new paper. Anyone who reads the ash-paper in the right light can see what a column used to say, which makes it the only reliable proof of a mis-tally."
    },
    {
      "id": "loc_hall_of_reckoning",
      "name": "The Hall of Reckoning",
      "description": "A cathedral-sized chamber with a single great scale of black iron. Souls are weighed against their own final ledger totals, and the verdict is not reopened once the pans settle."
    },
    {
      "id": "loc_ferrymans_tally_dock",
      "name": "The Ferryman's Tally Dock",
      "description": "A creaking pier where the ferryman cuts a notch in his pole for each soul carried across. His notches are an informal second ledger, and officials quietly dread the day it disagrees with theirs."
    }
  ],
  "factions": [
    {
      "id": "fac_guild_of_ink_bearers",
      "name": "The Guild of Ink-Bearers",
      "description": "The rank-and-file scribes who copy and carry entries between offices. They are underpaid in the only currency the dead have, which is remembered names, and they are quietly proud of their accuracy.",
      "location_ids": ["loc_threshold_registry", "loc_ferrymans_tally_dock"]
    },
    {
      "id": "fac_pennyweight_assessors",
      "name": "The Pennyweight Assessors",
      "description": "Senior auditors who guard the integrity of the totals. They treat every correction as an accusation against the office, and have never admitted a mis-tally in public.",
      "location_ids": ["loc_pennyweight_counting_house", "loc_hall_of_reckoning"]
    },
    {
      "id": "fac_keepers_of_ash",
      "name": "The Keepers of Ash",
      "description": "A secretive order of archivists who preserve the ghosts of burned pages. They trade in proof, and they help whoever offers them an unrecorded story to keep.",
      "location_ids": ["loc_ashen_scriptorium"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_return_to_life",
      "statement": "The dead cannot return to life; only their accounts move between columns, offices and verdicts.",
      "category": "metaphysics"
    },
    {
      "id": "rul_weighing_is_final",
      "statement": "Once the scale in the Hall of Reckoning settles, the verdict is sealed and no correction can be filed against it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ledger_is_truth",
      "statement": "A soul is exactly what its ledger says at the moment of weighing, not what it was in life.",
      "category": "metaphysics"
    },
    {
      "id": "rul_three_stamps",
      "statement": "A correction is valid only when stamped in three offices, in order, by three different hands.",
      "category": "social"
    },
    {
      "id": "rul_ash_remembers",
      "statement": "Burned ledger pages leave ash-paper that preserves what they once said, and ash-paper counts as evidence in any dispute.",
      "category": "physics"
    },
    {
      "id": "rul_names_as_wages",
      "statement": "Scribes of the dead are paid in remembered names, and a scribe whose name is forgotten by the living fades away.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_founding_of_columns",
      "name": "The Founding of the Four Columns",
      "description": "The first dead clerks divided the weighing of souls into Debts, Gifts, Silences and Oaths, replacing the older and arbitrary judgments of the river gods.",
      "era": "The Age of Reeds",
      "location_ids": ["loc_hall_of_reckoning", "loc_threshold_registry"]
    },
    {
      "id": "evt_great_misfiling",
      "name": "The Great Misfiling",
      "description": "A flood of plague dead was entered into the wrong ledger volumes, and thousands of souls were weighed unjustly. The Assessors still refuse to call it an error and name it an adjustment.",
      "era": "The Age of Ledgers",
      "location_ids": ["loc_pennyweight_counting_house", "loc_threshold_registry"]
    },
    {
      "id": "evt_ash_compact",
      "name": "The Ash Compact",
      "description": "After the Great Misfiling, the Keepers of Ash were granted the right to keep burned pages as evidence, in exchange for a promise never to publish what they read.",
      "era": "The Age of Ledgers",
      "location_ids": ["loc_ashen_scriptorium"]
    },
    {
      "id": "evt_ferrymans_discrepancy",
      "name": "The Ferryman's Discrepancy",
      "description": "The ferryman's notched pole once disagreed with the official count by a single soul. The matter was quietly closed, and nobody has said where that soul was weighed.",
      "era": "The Age of Audits",
      "location_ids": ["loc_ferrymans_tally_dock", "loc_hall_of_reckoning"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_correction_versus_pride",
      "name": "Correction Versus Pride",
      "description": "The Ink-Bearers carry a genuine error upward, but the Assessors cannot admit a fault without undermining their authority. The junior scribe must pass the correction through hostile hands before the deadline.",
      "faction_ids": ["fac_guild_of_ink_bearers", "fac_pennyweight_assessors"]
    },
    {
      "id": "cnf_price_of_proof",
      "name": "The Price of Proof",
      "description": "Only the Keepers of Ash can supply the evidence that proves the mis-tally, but they demand a story the scribe would rather not give, and the Assessors would punish the Keepers for helping.",
      "faction_ids": ["fac_keepers_of_ash", "fac_pennyweight_assessors"]
    }
  ]
}

