response.output:
{
  "world_id": "wld_leapfold_fair",
  "name": "The Leapfold Lanes",
  "description": "A gentle cozy-fantasy world in which a travelling fair unfolds only during leap-season, a thirteenth sliver of the year that exists solely for trade and tea. The fair's lanes are stitched from hedgerow, lantern-light and old bargains. When the season ends they fold like paper and drift to the next meadow. Sorrel Pennywhistle, a hedge-witch tea merchant, trails the fair hoping to win back her family's lost stall, the Ninth Stall. Every dispute in this world is settled by bargains, contests and trade, and the stakes are warmth, belonging and the right to pour a good cup. The tone is soft and unhurried, suitable for all ages.",
  "locations": [
    {
      "id": "loc_lantern_gate",
      "name": "The Lantern Gate",
      "description": "The fair's entrance, a hedge arch hung with paper lanterns. Each lantern is lit by a promise made by someone who passed through. Arrivals must trade a small true thing, such as a recipe or a joke, to enter."
    },
    {
      "id": "loc_ninth_stall",
      "name": "The Ninth Stall",
      "description": "A narrow, crooked tea stall at the quiet end of the Kettle Lane. It was once the Pennywhistle family's and now stands under another keeper's awning. Its shelves still remember the scent of Sorrel's grandmother's blends."
    },
    {
      "id": "loc_kettle_lane",
      "name": "Kettle Lane",
      "description": "The fair's busiest lane, lined with stalls of tea, honey, ribbons and mended things. Its cobbles warm underfoot near good bargains and cool near sour ones."
    },
    {
      "id": "loc_folding_green",
      "name": "The Folding Green",
      "description": "A wide meadow at the fair's heart where the lanes fold at season's end. Contests and trading-duels are held here beneath the Ledger Oak, a tree whose leaves record every bargain struck."
    }
  ],
  "factions": [
    {
      "id": "fac_hedge_witches",
      "name": "The Hedgerow Circle",
      "description": "Wandering hedge-witches who trade in herbs, teas and small kindnesses. They follow the fair from season to season and hold that stalls belong to the families who tend them.",
      "location_ids": ["loc_ninth_stall", "loc_kettle_lane"]
    },
    {
      "id": "fac_lane_wardens",
      "name": "The Lane Wardens",
      "description": "Keepers of the fair's order who fold and unfold the lanes. They watch the bargain ledger and rule that a stall belongs to whoever tends it when the season turns.",
      "location_ids": ["loc_lantern_gate", "loc_folding_green"]
    },
    {
      "id": "fac_brass_kettle_guild",
      "name": "The Brass Kettle Guild",
      "description": "A prosperous guild of tea-sellers who bought the Ninth Stall's lease years ago through a clever bargain. They are proud rather than cruel and love a well-argued contest.",
      "location_ids": ["loc_kettle_lane", "loc_ninth_stall"]
    }
  ],
  "rules": [
    {
      "id": "rul_leap_season",
      "statement": "The fair exists only in leap-season; when the final lantern burns out, every lane folds and the fair moves to a new meadow, leaving no trace behind.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bargain_binding",
      "statement": "A bargain spoken aloud beneath the Ledger Oak is binding and is written into its leaves; breaking one makes the speaker's tea go bitter until the bargain is set right.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_harm",
      "statement": "No one may raise a hand against another within the fair; disputes are settled only by bargains, contests and trade.",
      "category": "social"
    },
    {
      "id": "rul_true_toll",
      "statement": "Entry through the Lantern Gate requires a small true thing as a toll, and a false offering makes the lantern flicker.",
      "category": "social"
    },
    {
      "id": "rul_warm_cobbles",
      "statement": "The cobbles of the fair grow warm near honest trades and cool near deceptive ones.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_first_unfolding",
      "name": "The First Unfolding",
      "description": "The first leap-season fair unfolded from a single hedge and a bargain between a witch and a wandering merchant.",
      "era": "Age of Hedges",
      "location_ids": ["loc_folding_green"]
    },
    {
      "id": "evt_stall_lost",
      "name": "The Lost Lease",
      "description": "The Pennywhistle family lost the Ninth Stall when an unseasonal frost kept them from reaching the fair before the lanes closed, and the Brass Kettle Guild took the lease by bargain.",
      "era": "Age of Ledgers",
      "location_ids": ["loc_ninth_stall", "loc_lantern_gate"]
    },
    {
      "id": "evt_ledger_oak",
      "name": "The Planting of the Ledger Oak",
      "description": "The Lane Wardens planted the Ledger Oak so that every bargain would be remembered and honoured.",
      "era": "Age of Ledgers",
      "location_ids": ["loc_folding_green"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_ninth_stall_claim",
      "name": "The Claim on the Ninth Stall",
      "description": "Sorrel and the Hedgerow Circle seek to win back the Ninth Stall before the fair folds. The Brass Kettle Guild holds the lease by honest bargain and will yield only to a better one, so the matter must be settled by a tea contest and a trade of fair terms.",
      "faction_ids": ["fac_hedge_witches", "fac_brass_kettle_guild"]
    },
    {
      "id": "cnf_ledger_ruling",
      "name": "The Wardens' Ledger Ruling",
      "description": "The Lane Wardens must decide whether a bargain made under frost and haste should stand. Their ruling will shape how the fair treats every family that arrives late.",
      "faction_ids": ["fac_lane_wardens", "fac_hedge_witches"]
    }
  ]
}

