      "faction_ids": ["fac_hedge_witches", "fac_brass_kettle_guild"]
    },
    {
      "id": "cnf_ledger_ruling",
      "name": "The Wardens' Ledger Ruling",
      "description": "The Lane Wardens must decide whether a bargain made under frost and haste should stand. Their ruling will shape how the fair treats every family that arrives late.",
      "faction_ids": ["fac_lane_wardens", "fac_hedge_witches"]
    }
  ]
}

response.output:
{
  "world_id": "wld_ice_and_coin",
  "name": "The Tallow Drift",
  "description": "In a crowded stretch of the outer dark, a nomad market called Kessarine Hold clings to a captured comet, its streets carved into the ice and its docks strung out on miles of tether. Ships here manoeuvre on solar sails, spun tethers and bursts of reaction plumes. Nobody has ever fielded an energy weapon, so disputes are settled with grapnels, boarding cutlasses, hull-hooks and contract law. The comet is on a long orbit, and every few decades it swings close to its star. The Perihelion Burn is a scheduled, controlled venting of the comet's ice that flings the market back out on its orbit. It also scatters any fleet not tethered in the right place. The currency is ice-coin, stamped discs of sealed water that sublimate slowly. Wealth is therefore a perishable thing, and the market spends furiously as the burn approaches. Into this season of deadlines and debts falls the theft of a sealed star-map, the only chart of the safe line through the next orbit. Guild factotum Ilse Varrow-Kane must arbitrate the matter before the burn tears the fleet apart. The tone is swashbuckling: daring boardings, florid oaths, rival captains, and a market where every handshake is a contract and every contract is a trap.",
  "locations": [
    {
      "id": "loc_kessarine_hold",
      "name": "Kessarine Hold",
      "description": "The main market, a terraced warren of ice-cut arcades lit by trapped sunlight in lenses of clear glacier. Stalls sell reaction mass, sail-silk, forged manifests and hot broth. Every doorway has a notary rail where contracts are pressed into fresh ice."
    },
    {
      "id": "loc_tether_gallows",
      "name": "The Tether Gallows",
      "description": "A forest of braided cable runs out from the comet's equator, holding hundreds of moored ships. Captains duel on the cables with hooks and cutlasses in the weightless gap between hulls. Defaulters are hung out here on short tethers to await the burn."
    },
    {
      "id": "loc_ledger_vault",
      "name": "The Cold Ledger Vault",
      "description": "A deep ice cavern where the Guild keeps every debt as a column of cored ice, each layer a transaction. The vault is kept near freezing, and the clerks work in fur-lined suits. The sealed star-map was held here until it vanished."
    },
    {
      "id": "loc_vent_choir",
      "name": "The Vent Choir",
      "description": "A chain of geyser vents on the sunward face that will drive the Perihelion Burn. Pipe-organ stacks tune the jets, and the vent-wardens sing the pitch of each. Smugglers hide cargo in the cold side-chambers beneath the stacks."
    },
    {
      "id": "loc_black_sail_anchorage",
      "name": "Black Sail Anchorage",
      "description": "A lawless raft of hulks lashed together on the far side of the comet, beyond the Guild's notary rails. Privateers, defectors and fences trade here under black sails. Anything stolen in the Hold tends to surface here."
    }
  ],
  "factions": [
    {
      "id": "fac_coin_guild",
      "name": "The Guild of Sealed Coin",
      "description": "The chartered body that mints ice-coin, runs the notary rails and appoints factotums to arbitrate disputes. Its authority rests on the fiction that every contract is binding until the comet's next return.",
      "location_ids": ["loc_kessarine_hold", "loc_ledger_vault"]
    },
    {
      "id": "fac_tether_captains",
      "name": "The Tether Captains' Compact",
      "description": "A brawling association of ship-masters who moor on the cables. They prize freedom of passage and settle matters with hooks and cutlasses, and they resent the Guild's fees.",
      "location_ids": ["loc_tether_gallows", "loc_kessarine_hold"]
    },
    {
      "id": "fac_vent_wardens",
      "name": "The Vent Wardens",
      "description": "Singers and engineers who tune the geysers for the Perihelion Burn. They hold the only working knowledge of the burn's timing, and they claim the burn is sacred rather than a commodity.",
      "location_ids": ["loc_vent_choir"]
    },
    {
      "id": "fac_black_sails",
      "name": "The Black Sail Brotherhood",
      "description": "Privateers and fences who trade outside Guild law. They sell stolen charts to anyone who can pay in goods that do not melt.",
      "location_ids": ["loc_black_sail_anchorage", "loc_tether_gallows"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_energy_weapons",
      "statement": "No energy weapons exist anywhere in the Drift. Violence is done with hooks, cutlasses, grapnels, thrown ice and the timed use of reaction plumes.",
      "category": "technology"
    },
    {
      "id": "rul_sails_tethers_plumes",
      "statement": "Ships move only by solar sail, spun tethers and reaction plumes. Each plume spends reaction mass that must be bought or stolen.",
      "category": "physics"
    },
    {
      "id": "rul_ice_coin_decay",
      "statement": "Ice-coin sublimates slowly, losing roughly a tenth of its mass every year. Hoarding is ruinous, and the whole market spends harder as the comet nears perihelion.",
      "category": "physics"
    },
    {
      "id": "rul_burn_is_fixed",
      "statement": "The Perihelion Burn cannot be delayed or cancelled. Any ship not moored on the safe line by the final vent-song is flung off and scattered.",
      "category": "physics"
    },
    {
      "id": "rul_contract_in_ice",
      "statement": "A contract is binding only if pressed into fresh ice at a notary rail. Spoken oaths carry no weight, though everyone swears them anyway.",
      "category": "social"
    },
    {
      "id": "rul_factotum_arbitration",
      "statement": "A Guild factotum's ruling is final once the loser's coin is struck, and the factotum cannot rule on a matter in which they hold a debt.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_the_capture",
      "name": "The Capture of the Comet",
      "description": "Three fleets lashed cables to a wandering comet and fought over who would own it. The truce that followed became the first Guild charter.",
      "era": "Founding Age",
      "location_ids": ["loc_kessarine_hold"]
    },
    {
      "id": "evt_first_coin",
      "name": "The First Ice-Coin",
      "description": "The Guild stamped the first sealed discs of ice as a currency that could not be hoarded across orbits. This tied the market's life to the comet's rhythm.",
      "era": "Founding Age",
      "location_ids": ["loc_ledger_vault"]
    },
    {
      "id": "evt_scattering_of_the_nineteen",
      "name": "The Scattering of the Nineteen",
      "description": "In an earlier orbit, nineteen ships missed the safe line when a rival chart proved false. They were scattered across the dark, and the Captains have not forgiven the Guild.",
      "era": "Age of Burns",
      "location_ids": ["loc_tether_gallows", "loc_vent_choir"]
    },
    {
      "id": "evt_black_sail_schism",
      "name": "The Black Sail Schism",
      "description": "A fleet of captains broke from the Compact rather than pay Guild notary fees. They lashed their hulks together beyond the notary rails.",
      "era": "Age of Burns",
      "location_ids": ["loc_black_sail_anchorage"]
    },
    {
      "id": "evt_sealing_of_the_map",
      "name": "The Sealing of the Star-Map",
      "description": "The Wardens and the Guild jointly sealed the next orbit's safe line inside a wax-and-ice case. The seal cannot be broken until the final vent-song, and its theft threatens everyone.",
      "era": "Present Orbit",
      "location_ids": ["loc_ledger_vault", "loc_vent_choir"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_stolen_map",
      "name": "The Stolen Star-Map",
      "description": "Each faction accuses another of taking the sealed map. The Guild suspects the Brotherhood, the Captains suspect the Guild of staging the theft, and the Wardens will not say what they know.",
      "faction_ids": ["fac_coin_guild", "fac_black_sails", "fac_tether_captains", "fac_vent_wardens"]
    },
    {
      "id": "cnf_notary_fees",
      "name": "The Notary Fee War",
      "description": "The Captains refuse to pay the Guild's rising fees to moor on the cables. The Guild threatens to withhold mooring rights from defaulters before the burn.",
      "faction_ids": ["fac_coin_guild", "fac_tether_captains"]
    },
    {
      "id": "cnf_sacred_burn",
      "name": "Sacred Burn, Profitable Burn",
      "description": "The Wardens hold the burn to be sacred and want the market's ships moored by lot. The Guild wants berths on the safe line auctioned for coin before the discs melt.",
      "faction_ids": ["fac_vent_wardens", "fac_coin_guild"]
    }
  ]
}

