{
  "world_id": "wld_keep_the_wick",
  "name": "Harrowmere Parish",
  "description": "Harrowmere is a remote, pre-industrial moor parish of peat cutters, sheep folk and a single chapel. It is held together by one custom: a ring of wall lanterns along the old boundary stones must never all go dark on the same night. Each night the lamplighter walks the wall with a carried flame. Nobody will say plainly what the lanterns hold back, only that the moor takes notice of a parish that has gone fully dark. Last winter's ledger of lit nights has a page cut out. The new lamplighter inherits the wall, a fear the villagers will not name, and a gap in the record that someone wanted gone. The tone is slow, rural dread. The danger is in what the parish agrees not to say, more than in anything that appears on the moor.",
  "locations": [
    {
      "id": "loc_lantern_wall",
      "name": "The Lantern Wall",
      "description": "A ring of drystone boundary wall around the parish. Iron-hooded lanterns sit in niches roughly every hundred paces. Moss and tallow soot streak the stones, and between the niches the wall is unnaturally cold."
    },
    {
      "id": "loc_wickhouse",
      "name": "The Wickhouse",
      "description": "The lamplighter's low cottage, built against the wall's oldest stretch. Its hearth is the parish's mother-flame. Racks of trimmed wicks and a cellar of rendered tallow fill the rooms, and the previous lamplighter's belongings were never fully cleared."
    },
    {
      "id": "loc_vestry_of_st_ulric",
      "name": "The Vestry of St Ulric",
      "description": "The damp chapel vestry where the ledger of lit nights is kept in an oak chest. The ledger's winter section has one page sliced out close to the binding, and a different hand has since inked over the gap."
    },
    {
      "id": "loc_sallow_ford",
      "name": "Sallow Ford",
      "description": "A shallow crossing beyond the wall where the peat water runs rust-coloured. Villagers leave a stub of candle on its stones and do not look at the far bank after dusk."
    }
  ],
  "factions": [
    {
      "id": "fac_wardens_of_the_wall",
      "name": "Wardens of the Wall",
      "description": "Parish elders who fund the tallow, assign the lamplighter and enforce the lantern custom. They publicly claim it is mere tradition, but they guard the details of how it began.",
      "location_ids": ["loc_lantern_wall", "loc_vestry_of_st_ulric"]
    },
    {
      "id": "fac_tallow_widows",
      "name": "The Tallow Widows",
      "description": "Women who render the tallow and braid the wicks. They know that each batch is blended with something offered by the households, and that the amount owed has grown.",
      "location_ids": ["loc_wickhouse"]
    },
    {
      "id": "fac_ford_leavers",
      "name": "The Ford Leavers",
      "description": "A quiet fringe of crofters who believe the lanterns are a mistake and that the moor should be answered, not shut out. They leave offerings at the ford.",
      "location_ids": ["loc_sallow_ford"]
    }
  ],
  "rules": [
    {
      "id": "rul_never_all_dark",
      "statement": "If every lantern on the wall is dark at once, something crosses the boundary before dawn and a household is lost.",
      "category": "metaphysics"
    },
    {
      "id": "rul_borrowed_flame",
      "statement": "Every lantern must be lit from a flame carried from the Wickhouse hearth. A fresh spark struck at the wall burns, but the lantern it lights draws nothing back.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_engines_no_guns",
      "statement": "The parish has only hand tools, flint, fire and animal power. Nothing of metal-and-powder or machinery has ever reached the moor.",
      "category": "technology"
    },
    {
      "id": "rul_ledger_truth",
      "statement": "A lit night is recorded in the ledger by the lamplighter's own hand, and a night that goes unrecorded is treated by the parish as if it never happened.",
      "category": "social"
    },
    {
      "id": "rul_wick_burns_short",
      "statement": "A wick made from tallow of the parish burns exactly until dawn, but wick bought from outside the parish gutters within the hour.",
      "category": "physics"
    },
    {
      "id": "rul_do_not_name",
      "statement": "No one speaks of what the lanterns hold back by name, because speaking it at night is said to make the nearest lantern flicker.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_lighting",
      "name": "The First Lighting",
      "description": "The founders raised the wall after a winter in which the moor took whole farms. The first lantern was lit from the flame of a burning cart.",
      "era": "Founding years",
      "location_ids": ["loc_lantern_wall"]
    },
    {
      "id": "evt_tallow_levy",
      "name": "The Tallow Levy",
      "description": "The elders began taking a share from every household for the rendering. The Tallow Widows later recorded that the levy was also paid in something other than fat.",
      "era": "Early parish",
      "location_ids": ["loc_wickhouse"]
    },
    {
      "id": "evt_cut_page",
      "name": "The Cut Page",
      "description": "During last winter a page was cut from the ledger of lit nights, the same winter the previous lamplighter vanished from the Wickhouse without a body or farewell.",
      "era": "Last winter",
      "location_ids": ["loc_vestry_of_st_ulric", "loc_wickhouse"]
    },
    {
      "id": "evt_ford_candles",
      "name": "The Ford Candles Begin",
      "description": "Crofters started leaving candle stubs at Sallow Ford, and the stubs were found burnt down by morning with no one admitting to lighting them.",
      "era": "Recent years",
      "location_ids": ["loc_sallow_ford"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_the_missing_night",
      "name": "The Missing Night",
      "description": "The new lamplighter wants to recover what the cut page recorded, which is almost certainly a night the wall went dark. The Wardens need that night to remain unwritten.",
      "faction_ids": ["fac_wardens_of_the_wall"]
    },
    {
      "id": "cnf_answer_or_shut_out",
      "name": "Answer or Shut Out",
      "description": "The Ford Leavers want to let the lanterns fail, claiming the moor can be placated. The Wardens and Tallow Widows insist the wall is the only protection, even as the tallow cost grows.",
      "faction_ids": ["fac_ford_leavers", "fac_wardens_of_the_wall", "fac_tallow_widows"]
    }
  ]
}

